import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-129: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short129', durationInSeconds: 31.7, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};
const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);
type L = [string, string, ('good' | 'bad')?];
type Beat = { start: number; end: number; name: string; tag: string; chip: string; red?: boolean; lines: L[] };
const BEATS: Beat[] = [
  { start: 2.9, end: 6.4, name: 'Same input price', tag: 'Per 1M tokens.', chip: '$2', lines: [['GPT-6.1 Sol in', '$2.00', 'good'], ['Sonnet 5.5 in', '$2.00', 'good']] },
  { start: 6.4, end: 12.2, name: 'GPT-6.1 Sol', tag: 'Cache write.', chip: '$2.50', lines: [['write /1M', '$2.50', 'good'], ['kept for', '30 minutes']] },
  { start: 12.2, end: 17.7, name: 'Claude Sonnet 5.5', tag: 'Cache write.', chip: '$2.50', lines: [['write /1M', '$2.50', 'good'], ['kept for', '5 minutes']] },
  { start: 17.7, end: 22.1, name: 'Sonnet, longer', tag: 'Cache write.', chip: '$4', red: true, lines: [['write /1M', '$4.00', 'bad'], ['kept for', '1 hour']] },
  { start: 22.1, end: 24.9, name: 'Sol, longer', tag: 'Cache write.', chip: '$5', red: true, lines: [['write /1M', '$5.00', 'bad'], ['kept for', '12 hours']] },
  { start: 24.9, end: 28.3, name: 'Reading is cheap', tag: 'Cache hit /1M.', chip: '$0.10', lines: [['Sol read', '$0.10', 'good'], ['Sonnet read', '$0.10', 'good'], ['writing', '$2.50+', 'bad']] },
];

const Short129: React.FC = () => {
  const frame = useCurrentFrame();
  const HOOK_END = BEATS[0].start;
  const CTA = secToFrame(28.3);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'CACHE WRITES' }, { text: 'COST $2.50', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(HOOK_END)}>
        <CoverImage src="projects/short-129/cover.png" out={secToFrame(HOOK_END) - 10} />
        <HookTitle hold onDark kicker="AI API PRICING" lines={lines} />
      </FadeOut>
      {BEATS.map((b, i) => (
        <FadeOut key={i} at={i === BEATS.length - 1 ? CTA : secToFrame(b.end)}>
          <ToolCard name={b.name} tagline={b.tag} chip={b.chip} at={secToFrame(b.start) - 2} chipColor={b.red ? COLORS.danger : COLORS.accent2}>
            <Panel>
              {b.lines.map((l, j) => (
                <Line key={j} k={l[0]} v={l[1]} good={l[2] === 'good'} bad={l[2] === 'bad'} />
              ))}
            </Panel>
          </ToolCard>
        </FadeOut>
      ))}
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-129/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI API PRICING" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Both charge to write a cache.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short129;
